import { scenario } from './scenario.js';

export const STORAGE_KEY = 'ce-private-shift-drowsy-r2';
export const freshProgress = () => ({ version: 1, stage: 0, viewed: [], revealed: [], selected: [], answers: {}, tomorrow: null });
const choiceIds = {
  priority: ['12', '14', '9', 'charts'],
  action: scenario.actions.map(item => item.id),
  abg: scenario.interpretations.map(item => item.id),
  sbar: scenario.sbars.map(item => item.id),
};
export function sanitizeProgress(value) {
  if (!value || value.version !== 1) return freshProgress();
  const ids = scenario.cues.map(cue => cue.id);
  const safeList = (list, allowed) => Array.isArray(list) ? [...new Set(list.filter(id => allowed.includes(id)))] : [];
  const answers = {};
  for (const [key, allowed] of Object.entries(choiceIds)) if (allowed.includes(value.answers?.[key])) answers[key] = value.answers[key];
  if (Array.isArray(value.answers?.cues)) answers.cues = safeList(value.answers.cues, ids);
  let stage = Number.isInteger(value.stage) ? Math.max(0, Math.min(6, value.stage)) : 0;
  for (const [requiredStage, key] of [[2, 'priority'], [3, 'cues'], [4, 'action'], [5, 'abg'], [6, 'sbar']]) {
    if (stage >= requiredStage && answers[key] === undefined) { stage = requiredStage - 1; break; }
  }
  const revealed = safeList(value.revealed, ids);
  return { version: 1, stage, viewed: safeList(value.viewed, ['12', '14', '9']), revealed, selected: safeList(value.selected, revealed), answers, tomorrow: ['Yes', 'Maybe', 'No'].includes(value.tomorrow) ? value.tomorrow : null };
}
export function readProgress() {
  try { return sanitizeProgress(JSON.parse(localStorage.getItem(STORAGE_KEY))); } catch { return freshProgress(); }
}
export function cueResult(selected) {
  return {
    essential: scenario.cues.filter(cue => cue.tier === 'essential' && selected.includes(cue.id)).length,
    supporting: scenario.cues.filter(cue => cue.tier === 'supporting' && selected.includes(cue.id)).length,
  };
}

export const patients = [
  { room: '410', name: 'Ruth Alvarez', age: 74, label: 'Post-op knee', report: 'Post-op day 1, right total knee replacement. Up with a walker and one assist. High fall risk. Pain 3/10 at 0600.' },
  { room: '412', name: 'James Okafor', age: 58, label: 'Glucose due', report: 'Type 2 diabetes, day 2 for left leg cellulitis. 0600 glucose 78 mg/dL. Ate very little at dinner. Breakfast tray around 0745. Next glucose check due before breakfast.' },
  { room: '414', name: 'Leon Park', age: 66, label: 'Recent surgery', report: 'Open bowel surgery ended at 0300; arrived from PACU at 0430. 0700: HR 88, BP 128/74, RR 16, SpO2 96% on room air. Small spot on the abdominal dressing, outlined at 0600.' },
  { room: '416', name: 'Dana Whitfield', age: 39, label: 'Discharge', report: 'Admitted for a kidney infection, now feeling well. Discharge today; teaching not done yet. Ride expected around 0900.' },
];
export const staff = [
  { id: 'you', name: 'You', role: 'RN', early: 'Free at 0720', late: 'Go to 414 after coverage is arranged' },
  { id: 'jordan', name: 'Jordan', role: 'Nursing assistant', early: 'Finishing vitals; checked off for bedside glucose values', late: 'Reports 414 change at 0730, then free' },
  { id: 'priya', name: 'Priya', role: 'Charge RN', early: "Admission isn't here until 0730; can take one call", late: 'One short task to 0745; can still make staffing calls' },
  { id: 'dee', name: 'Dee', role: 'Buddy RN, rooms 418–422', early: 'Busy with her own rooms', late: 'Can watch rooms and take one patient task to 0800' },
  { id: 'sam', name: 'Sam', role: 'Unit secretary', early: 'Answers call lights by intercom', late: 'Relays messages, not nursing coverage' },
];
export const policy = 'A nursing assistant who is checked off may get a bedside glucose value and must report it to the RN right away. The RN reassesses the patient, interprets the result and decides next steps under the hypoglycemia protocol. Vital signs on a patient whose condition is changing are taken by the RN. Real rules depend on state law, competence and hospital policy.';
export const reasons = [
  { id: 'change', label: 'Most potential to change soon' },
  { id: 'due', label: 'Something time-sensitive is due' },
  { id: 'safety', label: 'Highest safety risk if left alone' },
  { id: 'quick', label: 'Quickest to finish' },
];
export function d1Feedback(room, reason) {
  if (reason === 'change') return room === '414' ? 'Reasonable. His surgery was recent, so a change is a real concern.' : "Good principle. 414's recent surgery is one reason a nurse might see him early; your room may have its own reasons.";
  if (reason === 'due') return room === '412' ? 'Reasonable. His glucose was low-normal, he ate little, and a check is due before breakfast.' : room === '416' ? 'Defensible. Starting teaching early avoids a rushed discharge. Make sure rooms that could change are seen early too.' : 'Fair. 412 and 416 are the rooms with something due soon.';
  if (reason === 'safety') return room === '410' ? 'Defensible. Her fall risk is real, and an early round can prevent her getting up alone.' : "Fair. 410 is the classic fall risk; 414's recent surgery and 412's low-normal glucose are other kinds of risk.";
  return 'Quick wins can help flow, but a first stop is usually chosen by who might change, not by speed.';
}
export const calls = {
  '410': 'I need to use the bathroom. Now, please.',
  '412': "I feel shaky and jittery. Something's off.",
  '416': 'My ride got here early. Can I go home?',
};
export const jordanDirections = {
  A: "She's a high fall risk. Use her walker, stay with her the whole time, leave her with the call light in reach and the bed low, and tell me right away if she's dizzy or in more pain.",
  B: 'Can you help 410 to the bathroom?',
};
export const hold416 = {
  A: "Your nurse knows your ride is here. They'll be in for your discharge teaching by about 0750.",
  B: 'Your nurse will be there soon.',
};
export const dispatchFeedback = {
  '412': {
    you: 'A nurse responds to the new symptoms now.', priya: 'Priya offered one call, accepted 412 and will hand him back at 0730.',
    jordan: "Jordan may collect a glucose value under this unit's policy, but cannot independently assess or decide what to do for a symptomatic patient. No nurse was sent to 412.",
    hold: 'A symptomatic patient is waiting without a nurse. Send a qualified nurse now.',
  },
  '410': {
    you: 'You can help her. Jordan could also assist with clear directions and follow-up.',
    priya: 'Priya can take this call, though Jordan could assist with clear directions and follow-up.',
    jordanA: 'Jordan has specific fall-safety directions and knows what change to report.',
    jordanB: 'Name her fall risk, how to assist her and what to report back.',
    hold: 'The message discourages getting up alone, but a high-fall-risk patient still waits for help.',
  },
  '416': {
    you: 'A nurse can start her discharge teaching.', priya: 'Priya can start teaching within her offered window if the papers are ready and tell you where she stopped.',
    jordan: 'Jordan can reinforce completed teaching, not provide discharge teaching.',
    holdA: 'She has a specific update and a realistic next check-in.', holdB: 'A vague promise leaves her unsure when a nurse will return.',
  },
};
export function dispatchText(room, draft) {
  const person = draft.assignments[room];
  const extra = room === '410' && person === 'jordan' ? draft.jordanDirection : room === '416' && person === 'hold' ? draft.hold416 : '';
  return dispatchFeedback[room][person + (extra || '')] || dispatchFeedback[room][person];
}
export const dispatchAcknowledgement = {
  '412': { priya: "On my way to 412. I'll call you with what I find; I have to hand him back at 0730." },
  '410': { priya: "I'll help her to the bathroom." },
  '416': { priya: "I'll start her teaching if her papers are ready and tell you where I got to." },
};
export const coverageOptions = [
  { id: 'A', text: "Dee, 414's pressure is dropping and I'm going now. Can you take 412: get his 0742 recheck, reassess him and act on it under the protocol? And watch 410 and 416 until 0800.", ack: "Got it. 412 at 0742, and I'm watching 410 and 416 until 0800.", feedback: 'A nurse who is free has accepted 412 and your other rooms out loud.' },
  { id: 'B', text: "Priya, can you take 412's 0742 recheck and reassessment as your short task? Dee, can you watch 410 and 416 until 0800?", ack: "Priya: Yes, that's my one task. I'll call you with the result. Dee: Watching 410 and 416 until 0800. When Priya finishes at 0745, I can take 412 through 0800 if she hands him over to me.", feedback: "Two nurses, each within what they offered. Priya's task ends at 0745; 412 still needs Dee's explicit handback." },
  { id: 'C', text: "Jordan, get 412's glucose at 0742 and give the number straight to Dee. Dee, can you see him with that number, act under the protocol, and watch 410 and 416?", ack: "Jordan: 0742, number to Dee. Dee: Got it. I'll go see him with Jordan's number, and watch 410 and 416 until 0800.", feedback: "Jordan collects the number. A named nurse who has accepted the job reassesses him and decides what's next." },
  { id: 'D', text: "Jordan, get 412's glucose at 0742 and call me with the number.", ack: 'Jordan: Will do.', feedback: "Jordan can collect the number, but he's still shaky and you'll be busy with 414. Name a nurse who can see him and act on it, and ask someone to watch your other rooms." },
  { id: 'E', text: 'Finish what you are doing first, then go to 414.', feedback: "A rising heart rate and falling pressure after surgery shouldn't wait. Hand off what you're doing and go." },
  { id: 'F', text: "Jordan, can you check 414's dressing and tell me if it looks bad?", feedback: "Assessing what the dressing and the patient's change mean is a nursing responsibility. A qualified nurse must respond to 414's deterioration without waiting for Jordan's judgment." },
];
export const v5Steps = [
  { id: 'i', text: 'Call Jordan to take over with her before you leave.', feedback: "Jordan: Coming now. I'll stay with her." },
  { id: 'ii', text: 'Help her back to bed first: walker, call light in reach, bed low. Then go.', feedback: 'About two minutes. She is back in bed before you leave.' },
  { id: 'iii', text: "Tell her to pull the cord when she's done, and go.", feedback: 'A high fall risk patient left alone in the bathroom may try to get up by herself.' },
];
export const helpOptions = [
  { id: 'provider', label: 'Call the surgical provider' }, { id: 'rapid', label: 'Call rapid response', note: 'Any staff member with significant concern can call' },
  { id: 'priya', label: 'Message Priya', note: "She can't leave her admission" },
  { id: 'recheck', label: 'Reinforce the dressing and recheck vitals in 15 minutes first' },
  { id: 'rounds', label: "Wait for the surgeon's 0800 rounds" },
];
export function helpFeedback(selected) {
  if (selected.includes('recheck')) return "You don't need another number. This trend and how he looks are enough to call now.";
  if (selected.includes('rounds')) return "That's 27 minutes for this trend. Call now.";
  if (selected.includes('provider') && selected.includes('rapid')) return 'Bedside help and the team who can act.' + (selected.includes('priya') ? ' Keeping the charge nurse informed is good teamwork.' : '');
  if (selected.includes('provider')) return 'The surgical team needs to know now.' + (selected.includes('priya') ? ' Keeping the charge nurse informed is good teamwork.' : '');
  if (selected.includes('rapid')) return "Right when you're seriously concerned; it brings help fast. Make sure the surgical team hears too, per your hospital's process." + (selected.includes('priya') ? ' Keeping the charge nurse informed is good teamwork.' : '');
  return "Priya should know, but she can't come to the bedside now. Call the provider or rapid response about this deterioration.";
}
export const looseEnds = [
  { id: '412', title: '412 / Mr. Okafor', accepted: "Check in on him when you can, and make sure the treating team knows about this morning's low so they can review his plan under your protocol.", acceptedFeedback: 'This follow-up keeps the morning low on the treating team’s radar; it stays queued until coverage is confirmed.', other: "He's back up. Nothing more needed.", otherFeedback: "A normal recheck isn't the end. The team should know about the low so they can decide whether his plan needs to change." },
  { id: '414', title: '414 / Your role', accepted: 'Stay with his care: carry out new orders as they come, keep reassessing and report how he responds.', acceptedFeedback: 'The team is here, and you remain responsible for reassessment and reporting.', other: 'The team has it now. Head back to your other rooms.', otherFeedback: "He's still your patient. Reassessing and reporting stay with you." },
  { id: 'coverage', title: 'Coverage / 410, 412, 416', accepted: "Dee, can you continue covering 410, 412 and 416 through 0830 while I stay with 414? Please call if anything changes. I'll let Priya know.", acceptedFeedback: 'The request names the rooms and end time. Coverage is not confirmed until Dee accepts out loud.', other: "They're stable. Let coverage end.", otherFeedback: "Coverage ends at 0800. Stable patients still need a nurse watching. Get a named nurse's acceptance before treating the loop as closed." },
  { id: '416', title: '416 / Ms. Whitfield', accepted: 'Ask the confirmed covering nurse to update her with a realistic time, and finish her teaching as soon as a nurse is free.', acceptedFeedback: 'This follow-up asks for an updated expectation and nurse-led teaching; it stays queued until coverage is confirmed.', other: 'Ask Jordan to go over her discharge papers so she can leave.', otherFeedback: "Teaching needs a nurse. Jordan can reinforce teaching but can't provide it." },
  { id: 'jordan', title: 'Jordan / delegated work', accepted: "Thank Jordan for flagging 414 fast. Tell her you'll take 414's vitals yourself while he's changing, and to tell you right away about any change in your other patients.", acceptedFeedback: "Jordan's report is acknowledged; a changing patient's vitals stay with the RN under this unit's policy.", other: "Ask Jordan to keep doing 414's vitals every 15 minutes.", otherFeedback: "Under this unit's policy, vitals on a patient whose condition is changing stay with the RN." },
];
export const references = [
  ['NCSBN / ANA National Guidelines for Nursing Delegation', 'https://www.ncsbn.org/public-files/NGND-PosPaper_06.pdf', 'Role, competence, acceptance, directions and follow-up; does not authorize specific local tasks.'],
  ['NIDDK Low Blood Glucose', 'https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/low-blood-glucose-hypoglycemia', 'General low-glucose information, not a hospital protocol.'],
  ['AHRQ Rapid Response Systems', 'https://psnet.ahrq.gov/primer/rapid-response-systems', 'General principles; facility criteria vary.'],
  ['AHRQ TeamSTEPPS Check-Back', 'https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/checkback.html', 'Closed-loop communication principle.'],
];

export const VERSION = '0.4';
export const STORAGE_KEY = 'ce_shift_005_v04';
export const ROOMS = ['410', '412', '414', '416'];
export const CALLS = ['410', '412', '416'];
export const DESTINATIONS = ['you', 'jordan', 'priya', 'hold'];
export const SEVERITY = ['Unsafe', 'Outside role', 'Revisit', 'Accepted with a note', 'Accepted'];

export function primaryReason(reasons) {
  return SEVERITY.find(reason => reasons.includes(reason)) || 'Accepted';
}
export function needsBridge(reasons) {
  return reasons.some(reason => ['Unsafe', 'Outside role', 'Revisit'].includes(reason));
}
export function fresh() {
  return {
    version: VERSION, stage: 0, selectedRoom: null,
    d1: null, d2Draft: { assignments: {}, jordanDirection: null, hold416: null }, d2: null,
    room412Seen: [], d3: null,
    d4: { phase: 0, revealed: [], helpDraft: [], help: null, reportDraft: [], report: null, checkback: null },
    d5: {}, coverageAcknowledged: false, tomorrow: null,
  };
}

export function canSubmitDispatch(draft) {
  const assigned = CALLS.every(room => DESTINATIONS.includes(draft.assignments[room]));
  if (!assigned) return false;
  const staff = ['you', 'jordan', 'priya'];
  if (staff.some(person => CALLS.filter(room => draft.assignments[room] === person).length > 1)) return false;
  if (draft.assignments['410'] === 'jordan' && !['A', 'B'].includes(draft.jordanDirection)) return false;
  if (draft.assignments['416'] === 'hold' && !['A', 'B'].includes(draft.hold416)) return false;
  return true;
}

const PLAN_KEYS = {
  'you:jordan:hold:A:A': 'V1',
  'you:jordan:priya:A:-': 'V2',
  'priya:jordan:you:A:-': 'V3',
  'you:priya:hold:-:A': 'V4',
  'priya:you:hold:-:A': 'V5',
};
export function dispatchPlan(draft) {
  const a = draft.assignments;
  return PLAN_KEYS[[a['412'], a['410'], a['416'], a['410'] === 'jordan' ? draft.jordanDirection : '-', a['416'] === 'hold' ? draft.hold416 : '-'].join(':')] || null;
}
export function evaluateDispatch(draft) {
  if (!canSubmitDispatch(draft)) throw new Error('Incomplete dispatch');
  const a = draft.assignments;
  const reasons = {
    '410': a['410'] === 'hold' ? ['Revisit'] : a['410'] === 'jordan' ? [draft.jordanDirection === 'A' ? 'Accepted' : 'Revisit'] : ['Accepted with a note'],
    '412': a['412'] === 'jordan' ? ['Outside role', 'Unsafe'] : a['412'] === 'hold' ? ['Unsafe'] : ['Accepted'],
    '416': a['416'] === 'jordan' ? ['Outside role'] : a['416'] === 'hold' ? [draft.hold416 === 'A' ? 'Accepted' : 'Revisit'] : ['Accepted'],
  };
  const plan = dispatchPlan(draft);
  const bridges = plan ? [] : [{ decision: 'D2', original: structuredClone(draft), story: 'V1', text: "Taking the safer approach: you go to 412, Jordan helps Ms. Alvarez, and Sam tells Ms. Whitfield you'll be in by about 0750." }];
  return { submitted: structuredClone(draft), reasons, plan, storyPlan: plan || 'V1', bridges };
}

export function evaluateCoverage(option, v5Step = null) {
  if (!['A', 'B', 'C', 'D', 'E', 'F'].includes(option)) throw new Error('Unknown coverage option');
  const reasons = { A: ['Accepted'], B: ['Accepted'], C: ['Accepted'], D: ['Revisit'], E: ['Unsafe'], F: ['Outside role', 'Unsafe'] }[option];
  const v5Reasons = v5Step ? ['i', 'ii', 'iii'].includes(v5Step) ? [v5Step === 'iii' ? 'Unsafe' : 'Accepted'] : null : null;
  if (v5Step && !v5Reasons) throw new Error('Unknown V5 step');
  const bridge = needsBridge(reasons) || (v5Reasons && needsBridge(v5Reasons));
  return { submitted: { option, v5Step }, reasons, v5Reasons, storyOption: bridge ? 'A' : option,
    bridges: bridge ? [{ decision: 'D3', original: { option, v5Step }, story: 'A', text: `Taking the safer approach: Dee takes 412 and watches 410 and 416 while you go to 414${v5Step === 'iii' ? ', and Jordan stays with Ms. Alvarez' : ''}.` }] : [] };
}

export function helpReasons(choices) {
  if (choices.includes('recheck') || choices.includes('rounds')) return ['Unsafe'];
  if (choices.includes('provider') || choices.includes('rapid')) return ['Accepted'];
  return ['Revisit'];
}
export function reportChips(revealed) {
  return [
    { id: 'trend', text: revealed.includes('vitals') ? 'HR 88 to 118 and BP 128/74 to 92/58' : 'HR 88 to 112 and BP 128/74 to 98/60 since 0700', required: true },
    ...(revealed.includes('dressing') ? [{ id: 'dressing', text: 'Bright red drainage spreading past the 0600 outline', required: true }] : []),
    { id: 'symptoms', text: revealed.includes('skin') ? 'Pale, anxious, feels faint; cool and clammy' : 'Pale, anxious, feels faint' },
    { id: 'surgery', text: 'Surgery ended at 0300' },
    { id: 'saturation', text: 'SpO2 96% at 0700' },
  ];
}
export function buildReport(selected, revealed) {
  const chips = reportChips(revealed);
  const selectedChips = chips.filter(chip => selected.includes(chip.id));
  return ["I'm concerned about postoperative deterioration.", ...(selected.includes('dressing') && revealed.includes('dressing') ? ["I'm also concerned about possible bleeding."] : []), ...selectedChips.map(chip => chip.text + '.'), 'I need you to see him now.'].join(' ');
}
export function evaluateReport(selected, revealed) {
  const available = reportChips(revealed);
  if (selected.length > 3 || selected.some(id => !available.some(chip => chip.id === id))) throw new Error('Invalid report chips');
  const missed = available.filter(chip => chip.required && !selected.includes(chip.id)).map(chip => chip.id);
  const saferIds = [...new Set([...selected, ...missed])];
  return { submitted: [...selected], revealed: [...revealed], reasons: missed.length ? ['Revisit'] : ['Accepted'], missed,
    line: buildReport(selected, revealed), saferLine: missed.length ? buildReport(saferIds, revealed) : null,
    bridges: missed.length ? [{ decision: 'D4 report', original: [...selected], story: saferIds, text: 'Taking the safer approach: lead with the observed findings you had available.' }] : [] };
}

export function evaluateD5(card, choice) {
  if (!['412', '414', 'coverage', '416', 'jordan'].includes(card) || !['accepted', 'other'].includes(choice)) throw new Error('Invalid loose end');
  const reasons = choice === 'accepted' ? ['Accepted'] : [card === '416' ? 'Outside role' : 'Revisit'];
  return { submitted: choice, reasons, storyChoice: 'accepted', bridges: choice === 'accepted' ? [] : [{ decision: `D5 ${card}`, original: choice, story: 'accepted', text: `Taking the safer approach: ${card} receives the accepted follow-up action.` }] };
}

export function allReasons(state) {
  return [
    ...Object.values(state.d2?.reasons || {}).flat(),
    ...(state.d3?.reasons || []), ...(state.d3?.v5Reasons || []),
    ...(state.d4.help?.reasons || []), ...(state.d4.report?.reasons || []), ...(state.d4.checkback?.reasons || []),
    ...Object.values(state.d5 || {}).flatMap(item => item.reasons),
  ];
}
export function ending(state) {
  const reasons = allReasons(state);
  if (reasons.some(r => r === 'Unsafe' || r === 'Outside role')) return 'C';
  if (reasons.includes('Revisit')) return 'B';
  return 'A';
}
export function canFinish(state) {
  return ['412', '414', 'coverage', '416', 'jordan'].every(card => !!state.d5[card]) && state.coverageAcknowledged;
}
export function dismissTeachingClaim(state) {
  return !['V2', 'V3'].includes(state.d2?.storyPlan);
}

import { useEffect, useState } from 'react';
import { patients, staff, policy, reasons, d1Feedback, calls, jordanDirections, hold416, dispatchText, dispatchAcknowledgement, coverageOptions, v5Steps, helpOptions, helpFeedback, looseEnds, references } from './data';
import { CALLS, SEVERITY, fresh, canSubmitDispatch, evaluateDispatch, evaluateCoverage, helpReasons, reportChips, evaluateReport, evaluateD5, ending, canFinish, dismissTeachingClaim } from './rules';
import { loadProgress, saveProgress, clearProgress } from './progress';
import './shift5.css';

const times = ['0700', '0715', '0720', '0724', '0730', '0733', '0800', '0830'];
const names = { you: 'You', jordan: 'Jordan', priya: 'Priya', hold: 'Hold / Sam' };
const stageNames = ['Report', 'Plan your round', 'Answer the lights', 'Room 412', 'Cover your rooms', 'Room 414', 'Close the loops', 'Debrief'];
const coverageSummaries = {
  A: 'Dee takes 412 and watches 410 + 416',
  B: 'Priya takes 412 briefly; Dee watches 410 + 416',
  C: 'Jordan gets the value; Dee reassesses 412',
  D: 'Jordan reports the value to you',
  E: 'Finish your current task first',
  F: 'Ask Jordan to assess 414’s dressing',
};
const staffResponsibilities = {
  early: {
    you: 'RN assessment and decisions',
    jordan: 'Routine assistance; reports changes to the RN',
    priya: 'Charge RN; can accept one call',
    sam: 'Relays messages, not nursing coverage',
  },
  late: {
    you: 'RN assessment of changing Room 414',
    jordan: 'Checked-off glucose value; reports to RN',
    priya: 'One short RN task or staffing call',
    dee: 'Named room coverage and RN reassessment',
  },
};
const coverageActionLabels = { A: 'Send handoff', B: 'Send handoff', C: 'Send handoff', D: 'Ask Jordan for the value', E: 'Finish current task', F: 'Ask Jordan to check 414' };
const coverageMessage = (option, plan) => option.id !== 'E' ? option.text : plan === 'V3' ? "Finish Ms. Whitfield's teaching, then go." : plan === 'V5' ? 'Finish with Ms. Alvarez, then go.' : "Stay with Mr. Okafor until his 0742 recheck, then go.";
const copy = async value => { try { await navigator.clipboard.writeText(value); return true; } catch { return false; } };

function Flags({ reasons: items }) {
  if (!items?.length) return null;
  const sorted = [...items].sort((a, b) => SEVERITY.indexOf(a) - SEVERITY.indexOf(b));
  return <span className="s5-flags" aria-label={`Primary result: ${sorted[0]}; all reasons: ${sorted.join(', ')}`}>{sorted.map((reason, i) => <span className={`s5-flag s5-${reason.toLowerCase().replaceAll(' ', '-')} ${i === 0 ? 'is-primary' : ''}`} key={`${reason}-${i}`}>{reason}</span>)}</span>;
}

function Choice({ selected, children, onClick, disabled = false, className = '', expanded }) {
  return <button type="button" className={`s5-choice ${selected ? 'is-selected' : ''} ${className}`} aria-pressed={!!selected} aria-expanded={expanded} onClick={onClick} disabled={disabled}>{children}</button>;
}

function UnitBoard({ state, onSelect, d1Draft }) {
  const stage = state.stage;
  const status = room => {
    if (stage === 0) return 'Report ready';
    if (stage === 1) {
      const order = state.d1?.order || d1Draft.order;
      return order.includes(room) ? `Visit ${order.indexOf(room) + 1}` : 'On assignment';
    }
    if (stage === 2) return CALLS.includes(room) ? 'Call light' : 'Quiet';
    if (room === '414') return stage >= 6 ? 'Team at bedside' : stage >= 4 ? 'Change reported' : 'Quiet';
    if (room === '412') return stage >= 6 ? state.coverageAcknowledged ? 'Dee to 0830' : 'Coverage expired' : 'Recheck due 0742';
    if (stage >= 6) return state.coverageAcknowledged ? 'Dee to 0830' : 'Coverage expired';
    if (stage >= 4) return state.d3 ? 'Coverage to 0800' : 'Coverage needed';
    return room === '416' ? 'Ride arrived' : 'Needs assistance';
  };
  return <section className={`s5-board ${stage === 4 ? 'is-compact' : ''}`} aria-label="Four-patient unit board">
    <div className="s5-board-head"><span>MED-SURG / FOUR ROOMS</span><strong>{stage === 5 && state.d3?.submitted?.v5Step === 'ii' ? '0735' : times[stage]}</strong></div>
    <div className="s5-board-grid">{patients.map(patient => <button type="button" key={patient.room} className={`s5-room ${state.selectedRoom === patient.room ? 'is-active' : ''} ${stage === 2 && CALLS.includes(patient.room) ? 'is-calling' : ''} ${patient.room === '414' && stage >= 4 && stage < 7 ? 'is-changing' : ''}`} onClick={() => onSelect(patient.room)} aria-label={`Room ${patient.room}, ${patient.name}, ${status(patient.room)}`}>
      <span className="s5-room-number">{patient.room}</span><span className="s5-room-status">{status(patient.room)}</span><small>{patient.name}</small>
    </button>)}</div>
    {stage >= 4 && stage < 7 && <p className="s5-board-note">{stage === 6 ? state.coverageAcknowledged ? 'Dee accepted 410, 412 and 416 through 0830.' : '0800 coverage has ended. Dee has offered an extension; acceptance is pending.' : !state.d3 ? 'Coverage is not assigned yet. A named nurse must accept before you leave.' : state.d3.storyOption === 'B' ? 'Priya to Dee: 412 handoff accepted at 0745. Coverage ends 0800.' : 'Dee accepted coverage through 0800. A new handoff is needed afterward.'}</p>}
  </section>;
}

function Feedback({ children, reasons: items, bridge }) {
  return <div className="s5-feedback" role="status"><Flags reasons={items} /><p>{children}</p>{bridge && <p className="s5-bridge">{bridge}</p>}</div>;
}

function StaffAvailability({ phase }) {
  const ids = phase === 'late' ? ['you', 'jordan', 'priya', 'dee'] : ['you', 'jordan', 'priya', 'sam'];
  return <ul className="s5-staff-list" aria-label="Staff availability">
    {ids.map(id => {
      const person = staff.find(item => item.id === id);
      return <li key={id}><div className="s5-staff-name"><strong>{person.name}</strong><span>{person.role}</span></div><div><span className="s5-staff-availability">{person[phase]}</span><small>{staffResponsibilities[phase][id]}</small></div></li>;
    })}
  </ul>;
}

export default function Shift5({ embedded = false, trackSession = null, debrief = null }) {
  const [state, setState] = useState(() => trackSession ? trackSession.initial() : loadProgress());
  const [d1Draft, setD1Draft] = useState(() => state.uiDraft?.d1Draft || { order: [], reason: null });
  const [d3Draft, setD3Draft] = useState(() => state.uiDraft?.d3Draft || { option: null, v5Step: null });
  const [checkbackDraft, setCheckbackDraft] = useState(() => state.uiDraft?.checkbackDraft || null);
  const [copied, setCopied] = useState(false);
  useEffect(() => { const snapshot = { ...state, uiDraft: { d1Draft, d3Draft, checkbackDraft } }; if (trackSession) trackSession.persist(snapshot); else saveProgress(snapshot); }, [state, d1Draft, d3Draft, checkbackDraft, trackSession]);
  useEffect(() => {
    const heading = document.querySelector('.s5-scene h1');
    heading?.setAttribute('tabindex', '-1');
    heading?.focus({ preventScroll: true });
    window.scrollTo(0, 0);
  }, [state.stage]);
  const patch = update => {
    if (trackSession) {
      for (const key of ['d2', 'd3']) if (update[key] && !state[key]) trackSession.observe(key, update[key], state);
      for (const key of ['help', 'report']) if (update.d4?.[key] && !state.d4[key]) trackSession.observe(key, update.d4[key], state);
    }
    setState(current => ({ ...current, ...update }));
  };
  const next = () => setState(current => ({ ...current, stage: current.stage + 1, selectedRoom: null }));
  const restart = () => { if (!trackSession) clearProgress(); setState(trackSession ? trackSession.restart() : fresh()); setD1Draft({ order: [], reason: null }); setD3Draft({ option: null, v5Step: null }); setCheckbackDraft(null); };
  const submitD1 = () => { if (d1Draft.order.length === 4 && d1Draft.reason) patch({ d1: structuredClone(d1Draft) }); };
  const setAssignment = (room, person) => setState(current => ({ ...current, d2Draft: { ...current.d2Draft, assignments: { ...current.d2Draft.assignments, [room]: person } } }));
  const submitD2 = () => { if (canSubmitDispatch(state.d2Draft)) patch({ d2: evaluateDispatch(state.d2Draft) }); };
  const submitD3 = () => { if (d3Draft.option && (state.d2.storyPlan !== 'V5' || d3Draft.v5Step)) patch({ d3: evaluateCoverage(d3Draft.option, state.d2.storyPlan === 'V5' ? d3Draft.v5Step : null) }); };
  const toggleRevealed = id => setState(current => ({ ...current, d4: { ...current.d4, revealed: current.d4.revealed.includes(id) ? current.d4.revealed : [...current.d4.revealed, id] } }));
  const toggleHelp = id => setState(current => { const exclusive = ['recheck', 'rounds']; const prev = current.d4.helpDraft; const values = exclusive.includes(id) ? [id] : [...prev.filter(item => !exclusive.includes(item)), ...(prev.includes(id) ? [] : [id])].filter(item => item !== id || !prev.includes(id)); return { ...current, d4: { ...current.d4, helpDraft: values } }; });
  const submitHelp = () => { const selected = state.d4.helpDraft; if (!selected.length) return; const reasons = helpReasons(selected); patch({ d4: { ...state.d4, help: { submitted: [...selected], reasons, bridges: reasons[0] === 'Accepted' ? [] : [{ decision: 'D4 help', original: selected, story: ['provider', 'rapid'], text: 'Taking the safer approach: you call the surgical provider and rapid response now.' }] }, phase: 1 } }); };
  const toggleChip = id => setState(current => { const draft = current.d4.reportDraft; return { ...current, d4: { ...current.d4, reportDraft: draft.includes(id) ? draft.filter(item => item !== id) : draft.length < 3 ? [...draft, id] : draft } }; });
  const submitReport = () => patch({ d4: { ...state.d4, report: evaluateReport(state.d4.reportDraft, state.d4.revealed), phase: 2 } });
  const submitCheckback = () => { if (!checkbackDraft) return; const good = checkbackDraft === 'repeat'; patch({ d4: { ...state.d4, checkback: { submitted: checkbackDraft, reasons: [good ? 'Accepted' : 'Revisit'], bridges: good ? [] : [{ decision: 'D4 check-back', original: checkbackDraft, story: 'repeat', text: 'Taking the safer approach: you repeat the plan back and the responder confirms it.' }] }, phase: 3 } }); };
  const submitEnd = (card, choice) => setState(current => ({ ...current, d5: { ...current.d5, [card]: evaluateD5(card, choice) } }));
  const acknowledgeCoverage = () => patch({ coverageAcknowledged: true });
  const first = state.d1?.order?.[0];
  const d2Plan = state.d2?.storyPlan;
  const room412Owner = ['V3', 'V5'].includes(d2Plan) ? 'Priya' : 'You';
  const optional = [
    { id: 'skin', label: 'Skin', finding: 'Cool and clammy.' },
    { id: 'dressing', label: 'Dressing', finding: 'Bright red drainage, now well past the 0600 pen outline.' },
    { id: 'vitals', label: 'Current vitals', finding: `${state.d3?.submitted?.v5Step === 'ii' ? '0735' : '0733'}: HR 118, BP 92/58, RR 22, SpO2 95% on room air.` },
    { id: 'trend', label: 'Full trend', finding: `0430/0600/0700/0730/${state.d3?.submitted?.v5Step === 'ii' ? '0735' : '0733'}: HR 84/86/88/112/118; systolic BP 132/130/128/98/92.` },
  ];
  return <div className={`s5-app${embedded ? ' is-embedded' : ''}`}>
    <header className="s5-header"><span className="s5-mark">CE</span><span><strong>THE SHIFT</strong><small>SHIFT-005 / Which Patient First?</small></span><button type="button" className="s5-reset" onClick={restart}>Start over</button></header>
    <div className="s5-layout"><aside className="s5-rail"><UnitBoard state={state} d1Draft={d1Draft} onSelect={room => patch({ selectedRoom: room })} />{state.stage === 2 && !state.d2 && <div className="s5-rail-staff"><h2>Who’s available?</h2><StaffAvailability phase="early" /></div>}<details className="s5-team"><summary>View delegation rules</summary><p>{policy}</p></details></aside>
      <main className="s5-main" id="main"><div className="s5-progress"><span>Step {state.stage + 1} of 8</span><span>{stageNames[state.stage]}</span></div>
